SELECT COUNT(*) FROM votes as v, comments as c, postLinks as pl, posts as p WHERE p.Id = pl.PostId AND p.Id = c.PostId AND p.Id = v.PostId AND v.CreationDate<=CAST('2014-09-11 00:00:00' AS TIMESTAMP) AND c.CreationDate>=CAST('2010-08-01 12:12:41' AS TIMESTAMP) AND pl.LinkTypeId=1 AND pl.CreationDate<=CAST('2014-08-11 17:26:31' AS TIMESTAMP)
